               cs23*ps4(2, 3, 3, 3, 3) + cs439*cs535 + cs441*ps3(2, 3, 3, 1) + cs447*ps2(2, 3, 3) &
               + cs453*ps2(2, 3, 4) + cs463*ps2(2, 3, 2) + cs469*ps2(2, 3, 1) + cs50*ps4(2, 3, 3, &
               3, 2) - cs51*ps4(2, 3, 3, 3, 1) + cs94*ps3(3, 3, 3, 3) + cs97*ps3(3, 3, 3, 4) + &
               ps1(3, 1)*(cs114*cs442 + cs141*cs414 + cs187*cs45 + cs19*cs543 + cs354*ps2(3, 3, 2) &
