               cs69*ps3(2, 3, 3, 2) + ps1(3, 1)*(cs177 + cs179 - cs42 + cs45*cs512)) + ps2(3, 3, &
               1)*(cs15*cs187 + cs181 + cs19*cs542 + cs433) + ps1(3, 2)*(-cs174*cs477 - &
               cs178*cs536 + cs19*cs541 - cs204*cs394 + cs361*ps2(3, 3, 1) - cs389*ps0(4)*ps2(3, &
               3, 4) + cs391*ps2(3, 3, 2) + cs455*ps2(2, 3, 2) + cs464*ps2(2, 3, 1) - &
               cs475*ps0(4)*ps2(2, 3, 4) + cs476*ps1(2, 1) + cs537*ps1(3, 4) + cs540*ps1(3, 1) + &
               cs69*ps3(2, 3, 3, 1)) + ps2(3, 3, 2)*((1.0_wp/4.0_wp)*cs11*cs236*cs30*cs7*ps2(2, 3, &
