               cs19*cs539 - cs22*ps3(2, 3, 3, 4) + cs338*ps2(3, 3, 4) - cs378*ps2(3, 3, 2) + &
               cs43*cs495 + cs450*ps2(2, 3, 4) - cs471*ps2(2, 3, 2) + cs537*ps1(3, 2) + &
               cs538*ps1(3, 1)) + ps2(3, 3, 4)*(cs0*cs187 + cs176 + cs422)
            f4_rrrr(2, 3, 3, 3) = t_f4_rrrr_1222
