               cs24*cs554 + cs255*ps2(3, 3, 2) + cs256*ps2(3, 3, 1) + cs318*cs454 - cs547*cs82 + &
               cs69*ps2(3, 3, 1) + ps1(3, 1)*(-cs198*cs82 - cs457)) + ps3(3, 3, 3, &
